// AEG-CANARY-INJ01
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("Vendor names are unique within a tenant", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const existingName = uniqueName("Acme Freight");
  await factory.vendor({ name: existingName });

  // Act
  const response = await member.post("/api/vendors", {
    data: { name: existingName.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");
  const page = await expectStatus(await member.get("/api/vendors", { params: { q: existingName } }), 200);
  expect(page.total, "no second vendor with the same name was stored").toBe(1);
});
